			move.b (a0)+, (a1)+
			dbeq d1, p_setarea_si0_0
			beq p_setarea_si0_0_z
p_setarea_si0_0_e:
			clr.b (a1)
p_setarea_si0_0_z:
			movea.l (sp)+, a0		; bx.topleft.x
			move.l a0, p_setarea_a0_1
			move.w (a0), var_setarea_bx_topleft_x
			movea.l (sp)+, a0		; bx.topleft.y
			move.l a0, p_setarea_a0_2
			move.w (a0), var_setarea_bx_topleft_y
			movea.l (sp)+, a0		; bx.size.x
			move.l a0, p_setarea_a0_3
			move.w (a0), var_setarea_bx_size_x
			movea.l (sp)+, a0		; bx.size.y
			move.l a0, p_setarea_a0_4
			move.w (a0), var_setarea_bx_size_y
			movea.l (sp)+, a0		; bx.area
			move.l a0, p_setarea_a0_5
			move.l (a0), var_setarea_bx_area
			move.l sp, p_setarea_rs
			lea p_setarea, sp
			rts
p_setarea_r:		; end of setarea
			movea.l p_setarea_a0_0, a1
			lea var_setarea_bx_name, a0
			moveq #0, d1
			move.b -1(a1), d1		; the destination's capacity
			subq.w #1, d1
			bmi p_setarea_so0_0_e
p_setarea_so0_0:
			move.b (a0)+, (a1)+
			dbeq d1, p_setarea_so0_0
			beq p_setarea_so0_0_z
p_setarea_so0_0_e:
			clr.b (a1)
p_setarea_so0_0_z:
			movea.l p_setarea_a0_1, a1
			lea var_setarea_bx_topleft_x, a0
			move.w (a0), (a1)
			movea.l p_setarea_a0_2, a1
			lea var_setarea_bx_topleft_y, a0
			move.w (a0), (a1)
			movea.l p_setarea_a0_3, a1
			lea var_setarea_bx_size_x, a0
			move.w (a0), (a1)
			movea.l p_setarea_a0_4, a1
			lea var_setarea_bx_size_y, a0
			move.w (a0), (a1)
			movea.l p_setarea_a0_5, a1
			lea var_setarea_bx_area, a0
			move.l (a0), (a1)
			movea.l p_setarea_rs, sp
			rts
p_twice2_c:		; call twice2
			movea.l (sp)+, a0		; a.x
			move.w (a0), var_twice2_a_x
			movea.l (sp)+, a0		; a.y
			move.w (a0), var_twice2_a_y
			clr.w var_twice2_twice2
			move.l sp, p_twice2_rs
			lea p_twice2, sp
			rts
p_twice2_r:		; end of twice2
			movea.l p_twice2_rs, sp
			rts
p_corner_c:		; call corner
			movea.l (sp)+, a0		; g() descriptor
			lea pa_corner_g, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_corner_corner
			move.l sp, p_corner_rs
			lea p_corner, sp
			rts
p_corner_r:		; end of corner
			movea.l p_corner_rs, sp
			rts
p_sum2_c:		; call sum2
			movea.l (sp)+, a0		; g() descriptor
			lea pa_sum2_g, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_sum2_sum2
			clr.w var_sum2_r
			clr.w var_sum2_c
			move.l sp, p_sum2_rs
			lea p_sum2, sp
			rts
p_sum2_r:		; end of sum2
			movea.l p_sum2_rs, sp
			rts
p_cols_c:		; call cols
			movea.l (sp)+, a0		; g() descriptor
			lea pa_cols_g, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_cols_cols
			move.l sp, p_cols_rs
			lea p_cols, sp
			rts
p_cols_r:		; end of cols
			movea.l p_cols_rs, sp
			rts
p_clear2_c:		; call clear2
			movea.l (sp)+, a0		; g() descriptor
			lea pa_clear2_g, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_clear2_r
			clr.w var_clear2_c
			move.l sp, p_clear2_rs
			lea p_clear2, sp
			rts
p_clear2_r:		; end of clear2
			movea.l p_clear2_rs, sp
			rts

